<?php declare(strict_types=1); ob_start(); $manager = (currentUser()['role'] ?? '') === 'manager'; ?>
<div class="container breadcrumb-line"><a href="/">Trang chủ</a><i class="fa-solid fa-chevron-right"></i><span>Quản lý sản phẩm</span></div>
<section class="container orders-section"><div class="section-heading"><div><span class="eyebrow">KHU VỰC QUẢN TRỊ</span><h1>Quản lý sản phẩm</h1><p class="muted mb-0">Danh sách gồm cả sản phẩm đang bán và đã ẩn.</p></div><a class="btn btn-dark rounded-pill" href="/admin/products/new">Thêm sản phẩm</a></div>
<?php if (is_array($flash) && isset($flash['message'])): ?><div class="alert alert-success" role="status"><?= h($flash['message']) ?></div><?php endif; ?><?php if (!$manager): ?><div class="alert alert-info">Bạn có quyền xem danh sách; thao tác thêm, sửa, ẩn và khôi phục dành cho quản lý.</div><?php endif; ?>
<?php if ($products === []): ?><div class="cart-empty"><i class="fa-solid fa-shirt"></i><h2>Chưa có sản phẩm</h2></div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Mã</th><th>Sản phẩm</th><th>Danh mục</th><th>Biến thể</th><th>Tồn kho</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($products as $product): $variants = is_array($product['variants'] ?? null) ? $product['variants'] : []; ?><tr><td><?= h($product['legacy_id'] ?? '') ?></td><td><?= h($product['name'] ?? '') ?></td><td><?= h($product['category']['name'] ?? '') ?></td><td><?= count($variants) ?></td><td><?= array_sum(array_map(static fn (array $v): int => (int) ($v['stock'] ?? 0), array_filter($variants, 'is_array'))) ?></td><td><?= ($product['active'] ?? false) ? 'Đang bán' : 'Đã ẩn' ?></td><td><div class="d-flex flex-wrap gap-2"><?php if ($manager): ?><a class="btn btn-sm btn-outline-dark" href="/admin/products/<?= rawurlencode((string) $product['legacy_id']) ?>/edit">Sửa</a><?php endif; ?><?php if (($product['active'] ?? false) && $manager): ?><form action="/admin/products/<?= rawurlencode((string) $product['legacy_id']) ?>/delete" method="post" onsubmit="return confirm('Ẩn sản phẩm này khỏi cửa hàng?')"><input type="hidden" name="csrf_token" value="<?= h(csrfToken()) ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Ẩn</button></form><?php elseif (!($product['active'] ?? false) && $manager): ?><form action="/admin/products/<?= rawurlencode((string) $product['legacy_id']) ?>/restore" method="post"><input type="hidden" name="csrf_token" value="<?= h(csrfToken()) ?>"><button class="btn btn-sm btn-outline-success" type="submit">Khôi phục</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
